import pyomo.environ as pyo

DATA = {
    "available_seats": [50, 60, 70],
    "demand": [30, 40],
    "revenue": [100, 150],
    "delta": [[1, 1, 0], [0, 1, 1]],
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    n_legs = len(d["available_seats"])
    n_packages = len(d["demand"])

    model = pyo.ConcreteModel()

    # Sets
    model.LEGS = pyo.RangeSet(0, n_legs - 1)
    model.PACKAGES = pyo.RangeSet(0, n_packages - 1)

    # Decision variable: units of each package to sell
    def sell_bounds(m, p):
        return (0, d["demand"][p])

    model.sell = pyo.Var(
        model.PACKAGES,
        domain=pyo.NonNegativeIntegers,
        bounds=sell_bounds,
    )

    # Objective: maximize total revenue
    def obj_rule(m):
        return sum(d["revenue"][p] * m.sell[p] for p in m.PACKAGES)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Constraint: seat capacity per flight leg
    def seat_capacity_rule(m, l):
        return sum(
            d["delta"][p][l] * m.sell[p] for p in m.PACKAGES
        ) <= d["available_seats"][l]

    model.seat_capacity = pyo.Constraint(model.LEGS, rule=seat_capacity_rule)

    return model
